/** Client-neutral SDK payload, always taken from this running platform build. */
import platformPackage from '../../../package.json' with { type: 'json' };
import { PLATFORM_APP_BUF_GEN_YAML } from '~agent/app-codegen';
import {
  APP_SDK,
  LEGACY_DATA_SDK,
  WORKFLOW_SDK,
  sdkImports,
} from '../../../sdk-internal/definitions';

// Vite embeds only the SDK artifacts generated by this build. Runtime cwd and
// the source repository are not part of the public SDK delivery contract.
const builtFiles = import.meta.glob<string>(
  [
    '../../../sdk-internal/{app,data,workflow}/package.json',
    '../../../sdk-internal/{app,data,workflow}/dist/**/*',
  ],
  { eager: true, query: '?raw', import: 'default' },
);

export async function sdkPayload(kind: 'app' | 'workflow') {
  const definitions =
    kind === 'app' ? [APP_SDK, LEGACY_DATA_SDK] : [WORKFLOW_SDK];
  const files: { path: string; contentBase64: string }[] = [];
  for (const definition of definitions) {
    const prefix = `../../../sdk-internal/${definition.directory}/`;
    const entries = Object.entries(builtFiles).filter(([file]) =>
      file.startsWith(prefix),
    );
    if (!entries.some(([file]) => /\/dist\/[^/]+\.js$/.test(file)))
      throw new Error('Built SDK artifacts are missing.');
    for (const [file, contents] of entries)
      files.push({
        path: `sdk/${definition.manifest.name}/${file.slice(prefix.length)}`,
        contentBase64: Buffer.from(contents).toString('base64'),
      });
  }
  files.push({
    path: 'import-map.json',
    contentBase64: Buffer.from(
      JSON.stringify({ imports: sdkImports(definitions) }, null, 2),
    ).toString('base64'),
  });
  if (kind === 'app')
    files.push({
      path: 'buf.gen.yaml',
      contentBase64: Buffer.from(PLATFORM_APP_BUF_GEN_YAML).toString('base64'),
    });
  return {
    files,
    ...(kind === 'app'
      ? {
          tooling: {
            bufVersion: platformPackage.devDependencies[
              '@bufbuild/buf'
            ].replace(/^\^/, ''),
            protocGenEsVersion: platformPackage.devDependencies[
              '@bufbuild/protoc-gen-es'
            ].replace(/^\^/, ''),
          },
        }
      : {}),
  };
}
